const output = [];
for (const item of $input.all()) {
  const binary = item.binary || {};
  const keys = Object.keys(binary).filter((k) => k.startsWith('attachment_'));
  for (const key of keys) {
    const file = binary[key];
    const fileName = (file.fileName || '').toLowerCase();
    const mime = (file.mimeType || '').toLowerCase();
    if (!mime.includes('pdf') && !fileName.endsWith('.pdf')) continue;
    output.push({
      json: {
        intake_source: 'gmail',
        gmail_message_id: item.json.id,
        email_subject: item.json.subject || '',
        email_from: item.json.from || '',
        vendor_name: '',
        invoice_number: '',
        invoice_date: '',
      },
      binary: { data: file },
    });
  }
}
if (!output.length) throw new Error('No PDF attachments found');
return output;

const src = $input.item.json;
const text = (src.text || '').replace(/\r/g, '');
const lines = [];
const rowRe = /^([A-Z0-9][A-Z0-9\-_]{2,})\s+(.+?)\s+(\d+(?:\.\d+)?)\s+\$?(\d+(?:\.\d{2})?)\s+\$?(\d+(?:\.\d{2})?)/gim;
let m;
while ((m = rowRe.exec(text)) !== null) {
  lines.push({
    sku: m[1].trim().toUpperCase(),
    description: m[2].trim(),
    qty: Number(m[3]),
    unit_price: Number(m[4]),
    line_total: Number(m[5]),
  });
}

const invMatch = text.match(/invoice\s*#?\s*([A-Z0-9\-]+)/i);
const dateMatch = text.match(/(\d{4}-\d{2}-\d{2}|\d{1,2}\/\d{1,2}\/\d{2,4})/);
const vendor = (src.email_from || '').split('<').pop().replace('>', '').split('@')[1] || 'distributor';

return {
  json: {
    intake_source: 'gmail',
    gmail_message_id: src.gmail_message_id || '',
    email_subject: src.email_subject || '',
    email_from: src.email_from || '',
    vendor_name: vendor,
    invoice_number: invMatch ? invMatch[1] : '',
    invoice_date: dateMatch ? dateMatch[1] : '',
    invoice_lines: lines,
    raw_text_preview: text.slice(0, 500),
  },
};

const inv = $input.item.json;
const priceRows = $('Sheet: Read Price_Book').all().map((i) => i.json);
const book = new Map();

for (const row of priceRows) {
  const sku = (row.sku || row.SKU || '').toString().trim().toUpperCase();
  if (!sku) continue;
  book.set(sku, {
    sku,
    description: row.description || row.item_description || '',
    contract_price: Number(row.contract_price || row.unit_price || row.price || 0),
  });
}

const auditId = 'INV-' + $now.toFormat('yyyyLLdd-HHmmss') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
const compared = [];
const unmatched = [];

for (const line of inv.invoice_lines || []) {
  const sku = (line.sku || '').toString().trim().toUpperCase();
  const invoicedPrice = Number(line.unit_price || 0);
  const bookRow = book.get(sku);

  if (!bookRow || !sku) {
    unmatched.push({ ...line, sku: sku || 'UNKNOWN', match_status: 'unmatched' });
    continue;
  }

  const contractPrice = bookRow.contract_price;
  const variancePct = contractPrice > 0
    ? Math.round(((invoicedPrice - contractPrice) / contractPrice) * 10000) / 100
    : 0;
  const overcharge = invoicedPrice > contractPrice
    ? Math.round((invoicedPrice - contractPrice) * (Number(line.qty) || 1) * 100) / 100
    : 0;

  compared.push({
    sku,
    description: line.description || bookRow.description,
    qty: Number(line.qty) || 1,
    invoiced_unit_price: invoicedPrice,
    contract_unit_price: contractPrice,
    variance_pct: variancePct,
    overcharge_amount: overcharge,
    match_status: 'matched',
    flagged: Math.abs(variancePct) > 2,
  });
}

return {
  json: {
    ...inv,
    audit_id: auditId,
    compared_lines: compared,
    unmatched_lines: unmatched,
    has_unmatched: unmatched.length > 0,
    matched_count: compared.length,
    unmatched_count: unmatched.length,
  },
};

const inv = $input.item.json;
const lines = inv.unmatched_lines || [];
return lines.map((line) => ({
  json: {
    ...inv,
    current_line: line,
    ai_prompt: 'Unmatched distributor invoice line. Suggest best Price_Book SKU match or mark as new_item.\nVendor: ' + (inv.vendor_name || '') + '\nLine: ' + JSON.stringify(line),
  },
}));

const base = $input.first().json;
const aiRows = $input.all().map((i) => {
  const out = i.json.output || i.json;
  const line = i.json.current_line || {};
  return {
    sku: (out.suggested_sku || line.sku || 'UNKNOWN').toUpperCase(),
    description: out.description || line.description || '',
    qty: Number(line.qty) || 1,
    invoiced_unit_price: Number(line.unit_price) || 0,
    contract_unit_price: 0,
    variance_pct: 0,
    overcharge_amount: 0,
    match_status: out.match_status || 'ai_suggested',
    flagged: false,
    ai_notes: out.notes || '',
    confidence_score: Number(out.confidence_score) || 0,
  };
});

return [{
  json: {
    ...base,
    ai_resolved_lines: aiRows,
  },
}];

const inv = $input.item.json;
const matched = inv.compared_lines || [];
const aiResolved = inv.ai_resolved_lines || [];
const allLines = [...matched, ...aiResolved];

const flagged = allLines.filter((l) => l.flagged);
const totalOvercharge = flagged.reduce((sum, l) => sum + (Number(l.overcharge_amount) || 0), 0);

return {
  json: {
    audit_id: inv.audit_id,
    received_at: $now.toISO(),
    intake_source: inv.intake_source,
    gmail_message_id: inv.gmail_message_id || '',
    vendor_name: inv.vendor_name || '',
    invoice_number: inv.invoice_number || '',
    invoice_date: inv.invoice_date || '',
    line_items_json: JSON.stringify(allLines),
    line_count: allLines.length,
    flagged_line_count: flagged.length,
    total_overcharge: Math.round(totalOvercharge * 100) / 100,
    matched_count: inv.matched_count || matched.length,
    unmatched_count: inv.unmatched_count || 0,
    has_variance_over_2pct: flagged.length > 0,
    status: 'pending_review',
    reviewed_at: '',
    dispute_sent_at: '',
  },
};

const body = $input.item.json.body || $input.item.json;
const lines = Array.isArray(body.invoice_lines) ? body.invoice_lines : (Array.isArray(body.lines) ? body.lines : []);
const normalized = lines.map((l) => ({
  sku: (l.sku || l.item_code || '').toString().trim().toUpperCase(),
  description: (l.description || l.item_name || '').trim(),
  qty: Number(l.qty ?? l.quantity ?? 1),
  unit_price: Number(l.unit_price ?? l.price ?? 0),
  line_total: Number(l.line_total ?? l.total ?? (Number(l.qty ?? 1) * Number(l.unit_price ?? 0))),
}));

if (!normalized.length) throw new Error('invoice_lines array is required for webhook intake');

return {
  json: {
    intake_source: 'webhook',
    gmail_message_id: '',
    email_subject: '',
    email_from: '',
    vendor_name: (body.vendor_name || body.vendor || '').trim(),
    invoice_number: (body.invoice_number || body.invoice_id || '').trim(),
    invoice_date: (body.invoice_date || '').trim(),
    invoice_lines: normalized,
    raw_text_preview: '',
  },
};
